export function summarizeBenchmark(runs) {
  const groups = groupRuns(runs, (run) => `${run.backend}/${run.arm}`);
  const taskGroups = groupRuns(runs, (run) => `${run.taskId}/${run.backend}/${run.arm}`);
  return {
    overall: Object.values(groups).map(summarizeGroup).sort(compareSummary),
    byTask: Object.values(taskGroups).map(summarizeGroup).sort(compareSummary),
    relative: compareArms(runs),
  };
}

export function formatMarkdown(report, metadata = {}) {
  const lines = [
    '# Browsemux Direct-vs-Mediated Benchmark',
    '',
    'Generated by `bench/runner.mjs`.',
    '',
    '| Setting | Value |',
    '| --- | --- |',
    `| Date | ${metadata.startedAt ?? ''} |`,
    `| Model | \`${metadata.model ?? ''}\` |`,
    `| Endpoint | \`${metadata.endpoint ?? ''}\` |`,
    `| Tasks | ${metadata.tasks?.join(', ') ?? ''} |`,
    `| Repeats | ${metadata.repeats ?? ''} |`,
    `| Snapshot limit | ${metadata.maxSnapshotChars ?? ''} characters |`,
    `| Max steps | ${metadata.maxSteps ?? 'task default'} |`,
    '',
    '## Overall',
    '',
    '| Backend | Arm | Verified | Median wall | p95 wall | Median input tokens | Median output tokens | Cost / verified task | Median model calls | Median retries | Median browser commands |',
    '| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |',
    ...report.overall.map((summary) => [
      summary.backend,
      summary.arm,
      `${summary.successes}/${summary.runs}`,
      formatMs(summary.medianWallMs),
      formatMs(summary.p95WallMs),
      formatNumber(summary.medianInputTokens),
      formatNumber(summary.medianOutputTokens),
      formatCost(summary.costPerVerifiedTask),
      formatNumber(summary.medianModelCalls),
      formatNumber(summary.medianModelRetries),
      formatNumber(summary.medianBrowserCommands),
    ].join(' | ') + ' |'),
    '',
    '## Relative Efficiency',
    '',
    'Negative percentages mean the mediated Browsemux arm is smaller or faster than the direct harness arm.',
    '',
    '| Backend | Verified delta | Wall-time change | Input-token change | Cost / verified task change |',
    '| --- | ---: | ---: | ---: | ---: |',
    ...report.relative.map((row) => [
      row.backend,
      formatSigned(row.successDelta),
      formatPercentChange(row.medianWallMs),
      formatPercentChange(row.medianInputTokens),
      formatPercentChange(row.costPerVerifiedTask),
    ].join(' | ') + ' |'),
    '',
    '## By Task',
    '',
    '| Task | Backend | Arm | Verified | Median wall | Median total tokens | Cost / verified task |',
    '| --- | --- | --- | ---: | ---: | ---: | ---: |',
    ...report.byTask.map((summary) => [
      summary.taskId,
      summary.backend,
      summary.arm,
      `${summary.successes}/${summary.runs}`,
      formatMs(summary.medianWallMs),
      formatNumber(summary.medianTotalTokens),
      formatCost(summary.costPerVerifiedTask),
    ].join(' | ') + ' |'),
    '',
    '## Interpretation Rules',
    '',
    '- The direct arm keeps a cumulative harness conversation. The Browsemux arm sends compact current state and bounded action history.',
    '- Both arms use the same browser executable, fixture tasks, model, snapshot limit, fresh-session policy, and deterministic success checks.',
    '- Wall time includes browser open, the decision loop, and browser close.',
    '- Browser commands count spawned `agent-browser` or BSK CLI processes. Model calls count successful JSON decision requests.',
    '- A fixture benchmark controls page drift and bot walls. It does not establish universal performance on live sites.',
    '- Provider-reported cost can change with routing, caching, and provider pricing. Keep the raw run JSON for audit.',
    '',
  ];
  return lines.join('\n');
}

export function normalizeUsage(usage = {}) {
  return {
    inputTokens: firstNumber(usage, [
      'prompt_tokens',
      'input_tokens',
      'inputTokens',
    ]),
    outputTokens: firstNumber(usage, [
      'completion_tokens',
      'output_tokens',
      'outputTokens',
    ]),
    cachedTokens: firstNumber(usage, [
      'cached_tokens',
      'cache_read_input_tokens',
      'input_cache_read_tokens',
      'cachedInputTokens',
    ]),
    totalTokens: firstNumber(usage, [
      'total_tokens',
      'totalTokens',
    ]),
    costUsd: firstNumber(usage, [
      'cost',
      'total_cost',
      'totalCost',
      'costUsd',
    ]),
  };
}

export function percentile(values, fraction) {
  const numbers = values
    .map(Number)
    .filter(Number.isFinite)
    .sort((left, right) => left - right);
  if (!numbers.length) return null;
  if (numbers.length === 1) return numbers[0];
  const bounded = Math.min(1, Math.max(0, fraction));
  const position = (numbers.length - 1) * bounded;
  const lower = Math.floor(position);
  const upper = Math.ceil(position);
  if (lower === upper) return numbers[lower];
  const weight = position - lower;
  return numbers[lower] * (1 - weight) + numbers[upper] * weight;
}

export function median(values) {
  return percentile(values, 0.5);
}

function summarizeGroup(runs) {
  const first = runs[0];
  const successes = runs.filter((run) => run.success).length;
  const usages = runs.map((run) => normalizeUsage(run.usage));
  const totalCost = usages.reduce((sum, usage) => sum + (usage.costUsd ?? 0), 0);
  return {
    backend: first.backend,
    arm: first.arm,
    taskId: first.taskId ?? null,
    runs: runs.length,
    successes,
    successRate: runs.length ? successes / runs.length : 0,
    medianWallMs: median(runs.map((run) => run.wallMs.total)),
    p95WallMs: percentile(runs.map((run) => run.wallMs.total), 0.95),
    medianDecisionMs: median(runs.map((run) => run.timings.decisionMs)),
    medianObservationMs: median(runs.map((run) => run.timings.observationMs)),
    medianActionMs: median(runs.map((run) => run.timings.actionMs)),
    medianInputTokens: median(usages.map((usage) => usage.inputTokens)),
    medianOutputTokens: median(usages.map((usage) => usage.outputTokens)),
    medianTotalTokens: median(usages.map((usage) => usage.totalTokens)),
    costTotal: totalCost || null,
    costPerVerifiedTask: successes ? totalCost / successes : null,
    medianModelCalls: median(runs.map((run) => run.modelCalls)),
    medianModelRetries: median(runs.map((run) => run.modelRetries)),
    medianBrowserCommands: median(runs.map((run) => run.browserCommands)),
    medianActions: median(runs.map((run) => run.actions)),
    invalidActions: runs.reduce((sum, run) => sum + run.invalidActions, 0),
  };
}

function compareArms(runs) {
  const backends = [...new Set(runs.map((run) => run.backend))];
  return backends.map((backend) => {
    const directRuns = runs.filter((run) => run.backend === backend && run.arm === 'direct');
    const browsemuxRuns = runs.filter((run) => run.backend === backend && run.arm === 'browsemux');
    const direct = directRuns.length ? summarizeGroup(directRuns) : emptySummary(backend, 'direct');
    const browsemux = browsemuxRuns.length ? summarizeGroup(browsemuxRuns) : emptySummary(backend, 'browsemux');
    return {
      backend,
      successDelta: Number.isFinite(browsemux.successRate)
        && Number.isFinite(direct.successRate)
        ? browsemux.successRate - direct.successRate
        : null,
      medianWallMs: ratioChange(browsemux.medianWallMs, direct.medianWallMs),
      medianInputTokens: ratioChange(browsemux.medianInputTokens, direct.medianInputTokens),
      costPerVerifiedTask: ratioChange(
        browsemux.costPerVerifiedTask,
        direct.costPerVerifiedTask,
      ),
    };
  });
}

function emptySummary(backend, arm) {
  return {
    backend,
    arm,
    successRate: null,
    medianWallMs: null,
    medianInputTokens: null,
    costPerVerifiedTask: null,
    medianModelRetries: null,
  };
}

function groupRuns(runs, keySelector) {
  const groups = {};
  for (const run of runs) {
    const key = keySelector(run);
    groups[key] ??= [];
    groups[key].push(run);
  }
  return groups;
}

function ratioChange(value, baseline) {
  if (!Number.isFinite(value) || !Number.isFinite(baseline) || baseline === 0) return null;
  return (value - baseline) / baseline;
}

function firstNumber(object, keys) {
  for (const key of keys) {
    const value = Number(object?.[key]);
    if (Number.isFinite(value)) return value;
  }
  return null;
}

function compareSummary(left, right) {
  return left.backend.localeCompare(right.backend)
    || armOrder(left.arm) - armOrder(right.arm)
    || String(left.taskId ?? '').localeCompare(String(right.taskId ?? ''));
}

function armOrder(arm) {
  return arm === 'direct' ? 0 : 1;
}

function formatMs(value) {
  if (!Number.isFinite(value)) return 'n/a';
  return `${Math.round(value).toLocaleString('en-US')} ms`;
}

function formatCost(value) {
  if (!Number.isFinite(value)) return 'n/a';
  if (value === 0) return '$0.000000';
  return `$${value < 0.01 ? value.toFixed(6) : value.toFixed(4)}`;
}

function formatNumber(value) {
  if (!Number.isFinite(value)) return 'n/a';
  return Number.isInteger(value)
    ? value.toLocaleString('en-US')
    : value.toLocaleString('en-US', { maximumFractionDigits: 1 });
}

function formatSigned(value) {
  if (!Number.isFinite(value)) return 'n/a';
  const points = value * 100;
  return `${points >= 0 ? '+' : ''}${points.toFixed(1)} pp`;
}

function formatPercentChange(value) {
  if (!Number.isFinite(value)) return 'n/a';
  const percent = value * 100;
  return `${percent >= 0 ? '+' : ''}${percent.toFixed(1)}%`;
}
